<?php require_once __DIR__ . '/../clude/foot.php'; ?><script>
(function($){
 function esc(v){return $('<div>').text(v==null?'':v).html()} function money(v){return Number(v||0).toFixed(2)}
 function render(d){var rows=d.rows||[],s=d.summary||d,all=$('#counter').val()==='ALL';$('#heading').text((all?'All counters':$('#counter option:selected').text())+' sales report: '+$('#from').val()+' to '+$('#to').val()).show();var diff=Number(s.difference||0),bad=Number(s.mismatches||0)>0;$('#summary').html('<div class="card"><b>'+Number(s.sales||0)+'</b><span>Sales</span></div><div class="card"><b>'+money(s.amount)+'</b><span>Sales total</span></div><div class="card"><b>'+money(s.item_total)+'</b><span>Sale items total</span></div><div id="variance-card" class="card '+(bad?'bad':'good')+'" role="button" tabindex="0" title="Click to show only sales with a variance"><b>'+money(diff)+'</b><span>'+(bad?'Mismatch difference — click to filter variance sales':'Balance difference — all totals match')+'</span></div>').show();var h='<div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Sale ID</th>'+(all?'<th>Counter</th>':'')+'<th>Shift</th><th>Time</th><th>Served by</th><th>Sale total</th><th>Items total</th><th>Status</th><th>Action</th></tr></thead><tbody>';if(!rows.length)h+='<tr><td colspan="9">No recorded sales.</td></tr>';rows.forEach(function(r){var ok=r.match_ok===true||r.match_ok===1||r.match_ok==='1';h+='<tr class="'+(ok?'':'mismatch-row')+'"><td>'+esc(r.sale_id)+'</td>'+(all?'<td>'+esc(r.counter_name||r.counter||'')+'</td>':'')+'<td>'+esc(r.shift)+'</td><td>'+esc(r.datime)+'</td><td>'+esc(r.username)+'</td><td>'+money(r.amount)+'</td><td>'+money(r.item_total)+'</td><td>'+(ok?'Tally':'Mismatch')+'</td><td><button class="btn btn-sm btn-primary view-sale-items" data-sale="'+esc(r.sale_id)+'">View</button></td></tr>'});$('#result').html(h+'</tbody></table></div>')}
 function load(){var c=$('#counter').val(),f=$('#from').val(),t=$('#to').val();if(!c||!f||!t){$('#result').html('<div class="alert alert-warning">Select a counter and both shift dates.</div>');return}$('#result').html('<div class="alert alert-info">Loading report...</div>');$.getJSON('api/repo_api.php',{action:'counter_sales',counter_id:c==='ALL'?0:c,from:f,to:t}).done(function(r){if(!r.ok){$('#result').html('<div class="alert alert-danger">'+esc(r.message)+'</div>');return}render(r.data||r)}).fail(function(){ $('#result').html('<div class="alert alert-danger">Could not load report.</div>')})}
 $('#search').on('click',load);$(document).on('click','.view-sale-items',function(){var id=$(this).data('sale');$('#items-modal').modal('show');$('#items-title').text('Sale #'+id+' items');$('#items-body').html('Loading...');$.getJSON('api/repo_api.php',{action:'sale_items',sale_id:id}).done(function(r){var d=r.data||r,h='<table class="table table-sm table-bordered"><thead><tr><th>Item</th><th>User</th><th>Counter</th><th>Category</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>';(d.items||[]).forEach(function(i){h+='<tr><td>'+esc(i.item_name)+'</td><td>'+esc(i.username||'Unknown user')+'</td><td>'+esc(i.counter_name||'Unknown counter')+'</td><td>'+esc(i.category_name)+'</td><td>'+esc(i.qty)+'</td><td>'+money(i.price)+'</td><td>'+money(i.total)+'</td></tr>'});$('#items-body').html(h+'</tbody></table>')}).fail(function(){$('#items-body').html('<div class="alert alert-danger">Could not load sale items.</div>')})});
 $('#search').on('click',load);$(document).on('click','#variance-card',function(){var card=$(this),rows=$('#result tbody tr');if(!rows.length)return;var active=card.data('active')===true;rows.each(function(){$(this).toggle(!active||$(this).hasClass('mismatch-row'))});card.data('active',!active).css('cursor','pointer');if(!active)card.find('span').text('Showing variance sales — click to show all');else card.find('span').text('Mismatch difference — click to filter variance sales')});$(document).on('keydown','#variance-card',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();$(this).trigger('click')}});$(document).on('click','.view-sale-items',function(){var id=$(this).data('sale');$('#items-modal').modal('show');$('#items-title').text('Sale #'+id+' items');$('#items-body').html('Loading...');$.getJSON('api/repo_api.php',{action:'sale_items',sale_id:id}).done(function(r){var d=r.data||r,h='<table class="table table-sm table-bordered"><thead><tr><th>Item</th><th>User</th><th>Counter</th><th>Category</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>';(d.items||[]).forEach(function(i){h+='<tr><td>'+esc(i.item_name)+'</td><td>'+esc(i.username||'Unknown user')+'</td><td>'+esc(i.counter_name||'Unknown counter')+'</td><td>'+esc(i.category_name)+'</td><td>'+esc(i.qty)+'</td><td>'+money(i.price)+'</td><td>'+money(i.total)+'</td></tr>'});$('#items-body').html(h+'</tbody></table>')}).fail(function(){$('#items-body').html('<div class="alert alert-danger">Could not load sale items.</div>')})});
$(document).on('click.saleMeta','.view-sale-items',function(){var id=$(this).data('sale');$.getJSON('api/repo_api.php',{action:'sale_items',sale_id:id}).done(function(r){var d=r.data||r,s=d.sale||{},items=d.items||[],users={},counters={};items.forEach(function(i){users[i.username||'Unknown user']=1;counters[i.counter_name||'Unknown counter']=1});var errors=[];if(s.match_ok===false||s.match_ok===0)errors.push('Sale total does not match the sale items total.');if(Object.keys(users).length>1)errors.push('Items belong to multiple users: '+Object.keys(users).join(', ')+'.');if(Object.keys(counters).length>1)errors.push('Items belong to multiple counters: '+Object.keys(counters).join(', ')+'.');var e=errors.length?'<div class="alert alert-danger"><b>Sale errors</b><ul><li>'+errors.join('</li><li>')+'</li></ul></div>':'<div class="alert alert-success">No sale ownership or total errors were detected.</div>';var info='<div class="row"><div class="col-md-3"><b>Raised</b><br>'+esc(s.datime)+'</div><div class="col-md-3"><b>Shift</b><br>'+esc(s.shift)+'</div><div class="col-md-3"><b>Counter</b><br>'+esc(s.counter_name)+'</div><div class="col-md-3"><b>Sale total</b><br>'+money(s.amount)+'<br><b>Items total</b><br>'+money(s.item_total)+'</div></div>';$('#items-body').prepend('<div class="sale-meta">'+info+e+'</div>');})});
function notify(icon,text,title){if(window.Swal&&typeof window.Swal.fire==='function'){Swal.fire({icon:icon,title:title||'',text:text});}else{window.alert(text);}}
$('#counter').on('change',function(){var all=$(this).val()==='ALL';$('#print-counter-summary').text(all?'Print Shift Summary':'Print Counter Summary').toggle(!!$(this).val());});
$('#print-counter-summary').on('click',function(){var c=$('#counter').val(),f=$('#from').val(),t=$('#to').val(),all=c==='ALL';if(!c||!f||!t){notify('warning','Select a counter and both shift dates first.','Print summary');return}if(!all&&f!==t){notify('warning','A counter summary can only be printed for one day. Set the same date in Shift from and Shift to.','One-day summary');return}$('#print-summary-title').text(all?'Shift Summary':'Counter Summary');$('#print-summary-question').text(all?'Queue the shift summary for this shift?':'Queue the counter summary for this counter and day?');$('#print-summary-counter').text(all?'All counters':$('#counter option:selected').text());$('#print-summary-date').text(f===t?f:f+' to '+t);$('#print-summary-modal').data('queue-action',all?'queue_shift':'queue').modal('show')});
$('#confirm-print-summary').on('click',function(){var $btn=$(this),c=$('#counter').val(),shift=$('#from').val(),action=$('#print-summary-modal').data('queue-action')||'queue';$btn.prop('disabled',true).text('Queueing...');$.ajax({url:'../counter/printsum.php',type:'POST',dataType:'json',data:{action:action,id:action==='queue'?c:0,shift:shift,summary_id:0}}).done(function(r){if(r&&r.ok){$('#print-summary-modal').modal('hide');notify('success',r.message||'Summary queued successfully.','Queued');}else{notify('error',(r&&r.message)||'Could not queue the summary.','Queue failed');}}).fail(function(xhr){var msg='Could not queue the summary.';if(xhr.responseJSON&&xhr.responseJSON.message)msg=xhr.responseJSON.message;notify('error',msg,'Queue failed')}).always(function(){$btn.prop('disabled',false).text('Queue Print')})});
})(jQuery);
